const memoryEntry = "---\nname: a\ndescription: A\nmetadata:\n  type: project\n---\n\nbody\n"

const memoryIndex = "# Memory index\n\n" +
	"GENERATED by `agents index`. Do not hand-edit — the pre-commit guard\n" +
	"regenerates this file and blocks the commit if it differs.\n\n" +
	"## project\n\n" +
	"- [a](a.md) — A\n"

const handoffEntry = "---\nlane: lane-a\nsession: s1\nstatus: reviewed\nwhen: 2026-08-10T09:00:00Z\n---\n\nbody\n"

const handoffIndex = "# Handoff index\n\n" +
	"GENERATED by `agents index`. Do not hand-edit — the pre-commit guard\n" +
	"regenerates this file and blocks the commit if it differs.\n\n" +
	"`reviewed` was written deliberately. `draft` was written automatically at\n" +
	"session end and has not been checked by anyone. Weigh them differently.\n\n" +
	"## lane-a\n\n" +
	"| when | status | session | file |\n" +
	"|---|---|---|---|\n" +
	"| 2026-08-10 09:00 | reviewed | s1 | [2026-08-10T09-00-00Z-s1.md](lane-a/2026-08-10T09-00-00Z-s1.md) |\n"

func newGuardRepo(t *testing.T) string {
	t.Helper()
	dir := t.TempDir()
	for _, args := range [][]string{
		{"init", "-b", "main"},
		{"config", "user.email", "t@example.com"},
		{"config", "user.name", "T"},
		{"config", "commit.gpgsign", "false"},
	} {
		gitCommand(t, dir, nil, args...)
	}
	return dir
}

func gitCommand(t *testing.T, dir string, stdin []byte, args ...string) []byte {
	t.Helper()
	cmd := exec.Command("git", args...)
	cmd.Dir = dir
	cmd.Stdin = bytes.NewReader(stdin)
	out, err := cmd.CombinedOutput()
	if err != nil {
		t.Fatalf("git %v: %v\n%s", args, err, out)
	}
	return out
}

func gitCommandEnv(t *testing.T, dir string, env []string, stdin []byte, args ...string) []byte {
	t.Helper()
	cmd := exec.Command("git", args...)
	cmd.Dir = dir
	cmd.Env = append(os.Environ(), env...)
	cmd.Stdin = bytes.NewReader(stdin)
	out, err := cmd.CombinedOutput()
	if err != nil {
		t.Fatalf("git %v: %v\n%s", args, err, out)
	}
	return out
}

func writeRepoFile(t *testing.T, root, rel, content string, mode fs.FileMode) {
	t.Helper()
	p := filepath.Join(root, filepath.FromSlash(rel))
	if err := os.MkdirAll(filepath.Dir(p), 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(p, []byte(content), mode); err != nil {
		t.Fatal(err)
	}
}

func stageFiles(t *testing.T, root string) { gitCommand(t, root, nil, "add", "-A") }

func commitFiles(t *testing.T, root string) {
	t.Helper()
	gitCommand(t, root, nil, "-c", "core.hooksPath=/dev/null", "commit", "-m", "baseline")
}

func withShippedConfig(t *testing.T) {
	t.Helper()
	_, file, _, ok := runtime.Caller(0)
	if !ok {
		t.Fatal("cannot locate guard test source")
	}
	config := filepath.Clean(filepath.Join(filepath.Dir(file), "../../../git/gitleaks.toml"))
	old := gitleaksConfigBytes
	gitleaksConfigBytes = func() ([]byte, error) { return os.ReadFile(config) }
	t.Cleanup(func() { gitleaksConfigBytes = old })
}

func fakeScanner(t *testing.T, scriptBody string) {
	t.Helper()
	dir := t.TempDir()
	script := "#!/bin/sh\nwhile IFS= read -r line; do :; done\n" + scriptBody + "\n"
	path := filepath.Join(dir, "gitleaks")
	if err := os.WriteFile(path, []byte(script), 0o755); err != nil {
		t.Fatal(err)
	}
	t.Setenv("PATH", dir+string(os.PathListSeparator)+os.Getenv("PATH"))
}

func fakeCleanScanner(t *testing.T) { fakeScanner(t, "exit 0") }

func withoutScanner(t *testing.T) {
	t.Helper()
	dir := t.TempDir()
	gitPath, err := exec.LookPath("git")
	if err != nil {
		t.Fatal(err)
	}
	if err := os.Symlink(gitPath, filepath.Join(dir, "git")); err != nil {
		t.Fatal(err)
	}
	t.Setenv("PATH", dir)
}

func blockingRule(findings []Finding, rule string) bool {
	for _, f := range findings {
		if f.Blocking && f.Rule == rule {
			return true
		}
	}
	return false
}

func ruleFindings(findings []Finding, rule string) []Finding {
	var out []Finding
	for _, f := range findings {
		if f.Rule == rule {
			out = append(out, f)
		}
	}
	return out
}

// Kills reading the working tree instead of `:<path>` in either direction.
func TestSecretScanConsumesTheStagedBlob(t *testing.T) {
	if _, err := exec.LookPath("gitleaks"); err != nil {
		t.Skip("gitleaks is not installed")
	}
	withShippedConfig(t)
	secret := "ghp_" + strings.Repeat("0123456789", 3) + "012345"

	t.Run("staged secret and clean worktree blocks", func(t *testing.T) {
		root := newGuardRepo(t)
		writeRepoFile(t, root, ".agents/note.md", secret+"\n", 0o644)
		stageFiles(t, root)
		writeRepoFile(t, root, ".agents/note.md", "clean working copy\n", 0o644)

		findings, err := Staged(root)
		if err != nil {
			t.Fatalf("Staged: %v", err)
		}
		if !blockingRule(findings, "github-pat") {
			t.Fatal("staged GitHub token was not blocked")
		}
		for _, f := range findings {
			if strings.Contains(f.Detail, secret) {
				t.Fatal("a finding disclosed the matched value")
			}
		}
	})

	t.Run("staged clean and secret worktree stays clean", func(t *testing.T) {
		root := newGuardRepo(t)
		writeRepoFile(t, root, ".agents/note.md", "clean staged copy\n", 0o644)
		stageFiles(t, root)
		writeRepoFile(t, root, ".agents/note.md", secret+"\n", 0o644)

		findings, err := Staged(root)
		if err != nil {
			t.Fatalf("Staged: %v", err)
		}
		if len(findings) != 0 {
			t.Fatalf("unstaged content affected the staged guard: %v", findings)
		}
	})
}

// Git exports repository selectors while running hooks. The repository/object
// selectors must not redirect reads, while GIT_INDEX_FILE is deliberately
// covered separately because it names the exact index a partial commit uses.
func TestStagedIgnoresInheritedGitRepositoryAndObjectSelectors(t *testing.T) {
	if _, err := exec.LookPath("gitleaks"); err != nil {
		t.Skip("gitleaks is not installed")
	}
	withShippedConfig(t)
	target := newGuardRepo(t)
	secret := "ghp_" + strings.Repeat("0123456789", 3) + "012345"
	writeRepoFile(t, target, ".agents/note.md", secret+"\n", 0o644)
	stageFiles(t, target)

	decoy := newGuardRepo(t)
	writeRepoFile(t, decoy, "main.go", "package main\n", 0o644)
	stageFiles(t, decoy)
	t.Setenv("GIT_DIR", filepath.Join(decoy, ".git"))
	t.Setenv("GIT_WORK_TREE", decoy)
	t.Setenv("GIT_OBJECT_DIRECTORY", filepath.Join(decoy, ".git", "objects"))

	findings, err := Staged(target)
	if err != nil {
		t.Fatalf("Staged: %v", err)
	}
	if !blockingRule(findings, "github-pat") {
		t.Fatal("inherited Git selectors redirected the guard away from its target repository")
	}
}

func TestStagedUsesTheActiveAlternateIndex(t *testing.T) {
	if _, err := exec.LookPath("gitleaks"); err != nil {
		t.Skip("gitleaks is not installed")
	}
	withShippedConfig(t)
	root := newGuardRepo(t)
	writeRepoFile(t, root, "main.go", "package main\n", 0o644)
	stageFiles(t, root)

	alternate := filepath.Join(t.TempDir(), "partial-commit.index")
	env := []string{"GIT_INDEX_FILE=" + alternate}
	gitCommandEnv(t, root, env, nil, "read-tree", "--empty")
	privateFixtureValue := "ghp_" + strings.Repeat("0123456789", 3) + "012345"
	writeRepoFile(t, root, ".agents/note.md", privateFixtureValue+"\n", 0o644)
	gitCommandEnv(t, root, env, nil, "add", ".agents/note.md")
	t.Setenv("GIT_INDEX_FILE", alternate)

	findings, err := Staged(root)
	if err != nil {
		t.Fatalf("Staged failed for the active alternate index: %v", err)
	}
	if !blockingRule(findings, "github-pat") {
		t.Fatal("the candidate blob in the active alternate index was not blocked")
	}
}

func TestStagedGitReadsDisableReplaceObjects(t *testing.T) {
	if _, err := exec.LookPath("gitleaks"); err != nil {
		t.Skip("gitleaks is not installed")
	}
	withShippedConfig(t)
	root := newGuardRepo(t)
	privateFixtureValue := "ghp_" + strings.Repeat("0123456789", 3) + "012345"
	writeRepoFile(t, root, ".agents/note.md", privateFixtureValue+"\n", 0o644)
	stageFiles(t, root)
	secretOID := strings.TrimSpace(string(gitCommand(t, root, nil, "rev-parse", ":.agents/note.md")))
	cleanOID := strings.TrimSpace(string(gitCommand(t, root, []byte("ordinary replacement\n"), "hash-object", "-w", "--stdin")))
	gitCommand(t, root, nil, "replace", secretOID, cleanOID)
	if got := string(gitCommand(t, root, nil, "cat-file", "blob", secretOID)); got != "ordinary replacement\n" {
		t.Fatal("replace-ref control did not substitute the staged blob")
	}

	findings, err := Staged(root)
	if err != nil {
		t.Fatalf("Staged: %v", err)
	}
	if !blockingRule(findings, "github-pat") {
		t.Fatal("a replace ref concealed a secret in the staged object")
	}
}

// Kills omitting the shipped domain extension or allowing a repository config
// to replace the trusted dotfiles config.
func TestShippedScannerConfigExtendsDefaultsAndIgnoresRepoConfig(t *testing.T) {
	if _, err := exec.LookPath("gitleaks"); err != nil {
		t.Skip("gitleaks is not installed")
	}
	withShippedConfig(t)
	cases := []struct {
		name string
		blob string
		rule string
	}{
		{"default github rule", "ghp_" + strings.Repeat("0123456789", 3) + "012345\n", "github-pat"},
		{"agent task extension", "gAAAAAB" + strings.Repeat("mZ", 18) + "\n", "encrypted-task-blob"},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			root := newGuardRepo(t)
			// A repository-owned config that disables rules must have no effect.
			writeRepoFile(t, root, ".gitleaks.toml", "[allowlist]\ndescription = \"disable\"\npaths = ['''.*''']\n", 0o644)
			writeRepoFile(t, root, ".agents/note.md", tc.blob, 0o644)
			stageFiles(t, root)
			findings, err := Staged(root)
			if err != nil {
				t.Fatalf("Staged: %v", err)
			}
			if !blockingRule(findings, tc.rule) {
				t.Fatalf("configured scanner did not report rule %q", tc.rule)
			}
		})
	}
}

// Kills a scanner result mapper that prints the whole report, Match, Secret,
// stderr, or a repository-controlled rule id.
func TestScannerMappingWhitelistsSafeFields(t *testing.T) {
	withShippedConfig(t)
	root := newGuardRepo(t)
	writeRepoFile(t, root, ".agents/note.md", "ordinary text\n", 0o644)
	stageFiles(t, root)

	t.Run("only rule and line survive", func(t *testing.T) {
		fakeScanner(t, `printf '%s' '[{"RuleID":"safe-rule","StartLine":7,"Secret":"DO-NOT-PRINT","Match":"DO-NOT-PRINT","Entropy":9.9}]'; exit 1`)
		findings, err := Staged(root)
		if err != nil {
			t.Fatalf("Staged: %v", err)
		}
		got := ruleFindings(findings, "safe-rule")
		if len(got) != 1 || got[0].Line != 7 || got[0].Detail != "gitleaks detected a secret in staged content" {
			t.Fatalf("unsafe or incomplete scanner mapping: %v", got)
		}
		if strings.Contains(fmt.Sprint(got), "DO-NOT-PRINT") {
			t.Fatal("scanner payload leaked into findings")
		}
	})

	t.Run("control characters in whitelisted fields fail the scan", func(t *testing.T) {
		fakeScanner(t, `printf '%s' '[{"RuleID":"FORGED\nBLOCK","StartLine":1}]'; exit 1`)
		if _, err := Staged(root); err == nil || strings.Contains(err.Error(), "FORGED\nBLOCK") {
			t.Fatalf("unsafe scanner field was not rejected safely: %v", err)
		}
	})

	for _, tc := range []struct {
		name string
		id   string
	}{
		{"bidirectional formatting", "safe\\u202erule"},
		{"printable delimiters", "safe][BLOCK"},
		{"oversized", strings.Repeat("a", 256)},
	} {
		t.Run(tc.name+" in rule id fails safely", func(t *testing.T) {
			fakeScanner(t, fmt.Sprintf("printf '%%s' '[{\"RuleID\":\"%s\",\"StartLine\":1}]'; exit 1", tc.id))
			_, err := Staged(root)
			if err == nil {
				t.Fatal("unsafe scanner rule identifier was accepted")
			}
			if strings.Contains(err.Error(), tc.id) {
				t.Fatal("unsafe scanner rule identifier leaked into the error")
			}
		})
	}
}

func TestBlockingScannerFindingSkipsGeneratedContentParsing(t *testing.T) {
	withShippedConfig(t)
	privateFixtureValue := "MATCHED-VALUE-MUST-STAY-PRIVATE"
	root := newGuardRepo(t)
	writeRepoFile(t, root, ".agents/memory/a.md", "---\nname: ["+privateFixtureValue+"\n---\n", 0o644)
	writeRepoFile(t, root, ".agents/memory/INDEX.md", memoryIndex, 0o644)
	stageFiles(t, root)
	fakeScanner(t, `printf '%s' '[{"RuleID":"test-rule","StartLine":1}]'; exit 1`)

	findings, err := Staged(root)
	if err != nil {
		t.Fatal("a blocking scanner finding should end content parsing with a finding, not an error")
	}
	if !blockingRule(findings, "test-rule") {
		t.Fatal("blocking scanner finding was lost")
	}
	if strings.Contains(fmt.Sprint(findings), privateFixtureValue) {
		t.Fatal("matched staged content crossed the public finding boundary")
	}
}

// Kills treating exit 1 as an execution error, accepting non-1 failures, or
// waving malformed result JSON through.
func TestScannerExitClassesFailClosed(t *testing.T) {
	withShippedConfig(t)
	root := newGuardRepo(t)
	writeRepoFile(t, root, ".agents/note.md", "ordinary text\n", 0o644)
	stageFiles(t, root)

	cases := []struct {
		name        string
		script      string
		wantErr     bool
		wantFinding bool
	}{
		{"clean exit zero", "exit 0", false, false},
		{"finding exit one", `printf '%s' '[{"RuleID":"test-rule","StartLine":2}]'; exit 1`, false, true},
		{"scanner failure", `printf '%s' 'SENSITIVE-STDERR' >&2; exit 7`, true, false},
		{"malformed finding json", `printf '%s' '{'; exit 1`, true, false},
		{"empty finding report", "exit 1", true, false},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			fakeScanner(t, tc.script)
			findings, err := Staged(root)
			if (err != nil) != tc.wantErr {
				t.Fatalf("error = %v, wantErr %v", err, tc.wantErr)
			}
			if err != nil && strings.Contains(err.Error(), "SENSITIVE-STDERR") {
				t.Fatal("scanner stderr leaked into the error")
			}
			if blockingRule(findings, "test-rule") != tc.wantFinding {
				t.Fatalf("finding presence = %v, want %v", blockingRule(findings, "test-rule"), tc.wantFinding)
			}
		})
	}
}

// Kills dropping the trusted config or redaction arguments while leaving the
// JSON mapper intact enough for the other subprocess tests to pass.
func TestScannerInvocationCarriesItsSecurityArguments(t *testing.T) {
	withShippedConfig(t)
	root := newGuardRepo(t)
	writeRepoFile(t, root, ".agents/note.md", "ordinary text\n", 0o644)
	stageFiles(t, root)
	fakeScanner(t, `
redact=0
config=0
format=0
report=0
while [ "$#" -gt 0 ]; do
  case "$1" in
    --redact) redact=1 ;;
    --config)
      shift
      case "$1" in /*) config=1 ;; esac
      ;;
    --report-format)
      shift
      [ "$1" = json ] && format=1
      ;;
    --report-path)
      shift
      [ "$1" = - ] && report=1
      ;;
  esac
  shift
done
[ "$redact$config$format$report" = 1111 ] || exit 8
exit 0`)
	findings, err := Staged(root)
	if err != nil || len(findings) != 0 {
		t.Fatalf("scanner security arguments were incomplete: findings=%v err=%v", findings, err)
	}
}

func TestTrustedConfigIsPrivateSnapshotIndependentOfHomeAndCleaned(t *testing.T) {
	t.Run("embedded bytes exactly match shipped canonical config", func(t *testing.T) {
		_, file, _, ok := runtime.Caller(0)
		if !ok {
			t.Fatal("cannot locate guard test source")
		}
		canonical := filepath.Clean(filepath.Join(filepath.Dir(file), "../../../git/gitleaks.toml"))
		want, err := os.ReadFile(canonical)
		if err != nil {
			t.Fatal(err)
		}
		if !bytes.Equal(embeddedGitleaksConfig, want) {
			t.Fatal("embedded scanner config drifted from git/gitleaks.toml")
		}
	})

	t.Run("embedded production source ignores HOME", func(t *testing.T) {
		oldSource := gitleaksConfigBytes
		gitleaksConfigBytes = defaultGitleaksConfigBytes
		t.Cleanup(func() { gitleaksConfigBytes = oldSource })
		t.Setenv("HOME", ".")
		fakeCleanScanner(t)
		root := newGuardRepo(t)
		writeRepoFile(t, root, ".agents/note.md", "ordinary text\n", 0o644)
		stageFiles(t, root)
		if findings, err := Staged(root); err != nil || len(findings) != 0 {
			t.Fatalf("embedded config source depended on HOME: findings=%v err=%v", findings, err)
		}
	})

	t.Run("scanner receives a private snapshot that is removed", func(t *testing.T) {
		old := gitleaksConfigBytes
		gitleaksConfigBytes = func() ([]byte, error) { return []byte("ORIGINAL-CONFIG\n"), nil }
		t.Cleanup(func() { gitleaksConfigBytes = old })
		observed := filepath.Join(t.TempDir(), "scanner-config-path")
		t.Setenv("OBSERVED_CONFIG", observed)
		fakeScanner(t, `
config=
while [ "$#" -gt 0 ]; do
  if [ "$1" = --config ]; then shift; config=$1; fi
  shift
done
[ -n "$config" ] || exit 8
printf '%s\n' "$config" > "$OBSERVED_CONFIG"
[ "$(stat -f '%Lp' "$config")" = 600 ] || exit 9
grep -q '^ORIGINAL-CONFIG$' "$config" || exit 10
exit 0`)
		root := newGuardRepo(t)
		writeRepoFile(t, root, ".agents/note.md", "ordinary text\n", 0o644)
		stageFiles(t, root)
		if findings, err := Staged(root); err != nil || len(findings) != 0 {
			t.Fatalf("private config snapshot was not used: findings=%v err=%v", findings, err)
		}
		b, err := os.ReadFile(observed)
		if err != nil {
			t.Fatal(err)
		}
		snapshot := strings.TrimSpace(string(b))
		if _, err := os.Lstat(snapshot); !os.IsNotExist(err) {
			t.Fatalf("private config snapshot survived the scan batch: %v", err)
		}
	})
}

func TestMissingScannerAndConfigAreBoundedFailures(t *testing.T) {
	withShippedConfig(t)

	t.Run("no staged agent blob needs no scanner", func(t *testing.T) {
		root := newGuardRepo(t)
		writeRepoFile(t, root, "src/main.go", "package main\n", 0o644)
		stageFiles(t, root)
		withoutScanner(t)
		findings, err := Staged(root)
		if err != nil || len(findings) != 0 {
			t.Fatalf("out-of-scope commit consulted scanner: findings=%v err=%v", findings, err)
		}
	})

	t.Run("an agent blob requires scanner", func(t *testing.T) {
		root := newGuardRepo(t)
		writeRepoFile(t, root, ".agents/note.md", "clean\n", 0o644)
		stageFiles(t, root)
		withoutScanner(t)
		_, err := Staged(root)
		if err == nil || !strings.Contains(err.Error(), "brew install gitleaks") {
			t.Fatalf("missing scanner did not fail with remediation: %v", err)
		}
	})

	t.Run("an agent blob requires trusted config", func(t *testing.T) {
		root := newGuardRepo(t)
		writeRepoFile(t, root, ".agents/note.md", "clean\n", 0o644)
		stageFiles(t, root)
		fakeCleanScanner(t)
		old := gitleaksConfigBytes
		gitleaksConfigBytes = func() ([]byte, error) { return nil, errors.New("unavailable") }
		t.Cleanup(func() { gitleaksConfigBytes = old })
		before := snapshotRepo(t, root)
		if _, err := Staged(root); err == nil {
			t.Fatal("missing dotfiles config was treated as a clean scan")
		}
		if after := snapshotRepo(t, root); !reflect.DeepEqual(before, after) {
			t.Fatal("missing-config failure mutated the repository")
		}
	})

	t.Run("an empty embedded config is not delegated as clean", func(t *testing.T) {
		root := newGuardRepo(t)
		writeRepoFile(t, root, ".agents/note.md", "clean\n", 0o644)
		stageFiles(t, root)
		fakeCleanScanner(t)
		old := gitleaksConfigBytes
		gitleaksConfigBytes = func() ([]byte, error) { return nil, nil }
		t.Cleanup(func() { gitleaksConfigBytes = old })
		if _, err := Staged(root); err == nil {
			t.Fatal("non-file dotfiles config was treated as a clean scan")
		}
	})
}

// Kills a generated-file comparison based on the unstaged working tree.
func TestGeneratedIndexesAreRenderedFromTheIndexSnapshot(t *testing.T) {
	withShippedConfig(t)
	fakeCleanScanner(t)

	t.Run("memory", func(t *testing.T) {
		root := newGuardRepo(t)
		writeRepoFile(t, root, ".agents/memory/a.md", memoryEntry, 0o644)
		writeRepoFile(t, root, ".agents/memory/INDEX.md", memoryIndex, 0o644)
		stageFiles(t, root)
		writeRepoFile(t, root, ".agents/memory/a.md", "broken unstaged content\n", 0o600)

		findings, err := Staged(root)
		if err != nil {
			t.Fatalf("Staged: %v", err)
		}
		if blockingRule(findings, "generated-file") {
			t.Fatal("unstaged memory content changed the expected generated bytes")
		}
	})

	t.Run("handoff", func(t *testing.T) {
		root := newGuardRepo(t)
		writeRepoFile(t, root, ".agents/reports/handoff/lane-a/2026-08-10T09-00-00Z-s1.md", handoffEntry, 0o644)
		writeRepoFile(t, root, ".agents/reports/handoff/INDEX.md", handoffIndex, 0o644)
		stageFiles(t, root)
		writeRepoFile(t, root, ".agents/reports/handoff/lane-a/2026-08-10T09-00-00Z-s1.md", "broken unstaged content\n", 0o600)

		findings, err := Staged(root)
		if err != nil {
			t.Fatalf("Staged: %v", err)
		}
		if blockingRule(findings, "generated-file") {
			t.Fatal("unstaged handoff content changed the expected generated bytes")
		}
	})
}

// memory.WriteIndex only owns INDEX.md at the memory root. A nested file with
// that basename is ignored by memory.List and cannot collide with the output.
func TestNestedIndexNameDoesNotCreateAFalseGeneratedFailure(t *testing.T) {
	withShippedConfig(t)
	fakeCleanScanner(t)
	root := newGuardRepo(t)
	writeRepoFile(t, root, ".agents/memory/a.md", memoryEntry, 0o644)
	writeRepoFile(t, root, ".agents/memory/INDEX.md", memoryIndex, 0o644)
	writeRepoFile(t, root, ".agents/memory/archive/index.md", "archived prose\n", 0o644)
	stageFiles(t, root)

	findings, err := Staged(root)
	if err != nil {
		t.Fatalf("nested memory file was treated as an index collision: %v", err)
	}
	if blockingRule(findings, "generated-file") {
		t.Fatal("a nested index basename changed the root memory index")
	}
}

