type worktreeFile struct {
	Mode fs.FileMode
	Data string
}

type repoSnapshot struct {
	Worktree map[string]worktreeFile
	Index    string
}

// snapshotRepo is intentionally independent of production guard helpers. It
// observes every worktree entry outside .git and Git's mode/stage/blob table.
func snapshotRepo(t *testing.T, root string) repoSnapshot {
	t.Helper()
	worktree := map[string]worktreeFile{}
	err := filepath.WalkDir(root, func(p string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		rel, err := filepath.Rel(root, p)
		if err != nil {
			return err
		}
		if rel == ".git" {
			return filepath.SkipDir
		}
		if rel == "." {
			return nil
		}
		info, err := os.Lstat(p)
		if err != nil {
			return err
		}
		item := worktreeFile{Mode: info.Mode()}
		switch {
		case info.Mode()&os.ModeSymlink != 0:
			item.Data, err = os.Readlink(p)
		case info.Mode().IsRegular():
			var b []byte
			b, err = os.ReadFile(p)
			item.Data = string(b)
		}
		if err != nil {
			return err
		}
		worktree[filepath.ToSlash(rel)] = item
		return nil
	})
	if err != nil {
		t.Fatal(err)
	}
	index := string(gitCommand(t, root, nil, "ls-files", "--stage", "-z"))
	return repoSnapshot{Worktree: worktree, Index: index}
}

func TestEveryStagedOutcomeIsObservational(t *testing.T) {
	withShippedConfig(t)
	cases := []struct {
		name    string
		files   map[string]string
		scanner string
		missing bool
	}{
		{"clean", map[string]string{"src/main.go": "package main\n"}, "exit 0", false},
		{"advisory", map[string]string{".agents/note.md": "note\n", "src/main.go": "package main\n"}, "exit 0", false},
		{"finding", map[string]string{".agents/note.md": "note\n"}, `printf '%s' '[{"RuleID":"test-rule","StartLine":1}]'; exit 1`, false},
		{"scanner missing", map[string]string{".agents/note.md": "note\n"}, "", true},
		{"scanner error", map[string]string{".agents/note.md": "note\n"}, "exit 7", false},
		{"malformed json", map[string]string{".agents/note.md": "note\n"}, `printf '%s' '{'; exit 1`, false},
		{"malformed tracked entry", map[string]string{".agents/memory/a.md": "broken\n", ".agents/memory/INDEX.md": memoryIndex}, "exit 0", false},
		{"missing generated index", map[string]string{".agents/memory/a.md": memoryEntry}, "exit 0", false},
		{"generated mismatch", map[string]string{".agents/memory/a.md": memoryEntry, ".agents/memory/INDEX.md": "wrong\n"}, "exit 0", false},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			root := newGuardRepo(t)
			for rel, content := range tc.files {
				writeRepoFile(t, root, rel, content, 0o640)
			}
			stageFiles(t, root)
			if tc.missing {
				withoutScanner(t)
			} else {
				fakeScanner(t, tc.scanner)
			}
			before := snapshotRepo(t, root)
			_, _ = Staged(root)
			after := snapshotRepo(t, root)
			if !reflect.DeepEqual(before, after) {
				t.Fatalf("Staged mutated repository state\nbefore: %#v\nafter:  %#v", before, after)
			}
		})
	}
}

