func TestStagedFindingsAreDeterministicallyOrdered(t *testing.T) {
	withShippedConfig(t)
	fakeScanner(t, `printf '%s' '[{"RuleID":"z-rule","StartLine":3},{"RuleID":"a-rule","StartLine":2}]'; exit 1`)
	root := newGuardRepo(t)
	for _, rel := range []string{".agents/z.md", ".agents/a.md"} {
		writeRepoFile(t, root, rel, "note\n", 0o644)
	}
	stageFiles(t, root)
	findings, err := Staged(root)
	if err != nil {
		t.Fatal(err)
	}
	got := append([]Finding(nil), findings...)
	if len(findings) != 4 {
		t.Fatalf("two scanner findings for each of two staged blobs = 4, got %d", len(findings))
	}
	sort.Slice(got, func(i, j int) bool {
		if got[i].Path != got[j].Path {
			return got[i].Path < got[j].Path
		}
		if got[i].Line != got[j].Line {
			return got[i].Line < got[j].Line
		}
		return got[i].Rule < got[j].Rule
	})
	if fmt.Sprint(got) != fmt.Sprint(findings) {
		t.Fatalf("findings are not stable: %v", findings)
	}
}
